cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE 32

// ---------------------------------------------------------------
// Simple tiled fp16 GEMM (accumulate in float)
// ---------------------------------------------------------------
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int N) {
    __shared__ half As[TILE][TILE];
    __shared__ half Bs[TILE][TILE];

    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;

    float acc = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE) {
        // Load A tile
        if (row < N && (t + threadIdx.x) < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + t + threadIdx.x];
        else
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        // Load B tile
        if ((t + threadIdx.y) < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[(t + threadIdx.y) * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        __syncthreads();

        // Compute partial product
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------
// Wrapper called from Python
// ---------------------------------------------------------------
void matmul_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    const int N = static_cast<int>(A.size(0));

    dim3 threads(TILE, TILE);
    dim3 blocks((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    matmul_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(A.data_ptr<half>()),
        reinterpret_cast<const half*>(B.data_ptr<half>()),
        reinterpret_cast<half*>(C.data_ptr<half>()),
        N);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}
'''

# ----------------------------------------------------------------------
# Build the extension
# ----------------------------------------------------------------------
matmul_ext = load_inline(
    name='matmul_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['matmul_fp16'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B using a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Expect fp16 tensors on the same CUDA device
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "Inputs must be fp16"
        assert A.shape == B.shape and A.dim() == 2, "Inputs must be square matrices"
        C = torch.empty_like(A)
        matmul_ext.matmul_fp16(A, B, C)
        return C
